# -*- coding: utf-8 -*-
# 카톡 미리보기 사진을 파란 헤드폰 그래픽으로
#  - 한국어(ssing.kr/app/)      → app/og_ko.jpg (글자 "파란소리")
#  - 영어·나머지 언어(app/en/ 등) → app/og.jpg   (글자 "ParanSori")
# 사진 주소 끝 ?v= 번호를 올려서 카톡이 예전 사진을 기억하지 않게
import os, re, sys, base64
EN = base64.b64decode("""""")
KO = base64.b64decode("""""")
ROOT = os.path.join('app', 'index.html')
if not os.path.isfile(ROOT):
    print('❌ app/index.html 이 없어요 — 프로젝트 폴더(C:\\apps\\mp3_player_new)에서 실행해 주세요'); sys.exit(1)
def same(p, data): return os.path.isfile(p) and open(p, 'rb').read() == data
og, og_ko = os.path.join('app', 'og.jpg'), os.path.join('app', 'og_ko.jpg')
if same(og, EN) and same(og_ko, KO) and 'og_ko.jpg' in open(ROOT, encoding='utf-8').read():
    print('이미 적용돼 있어요'); sys.exit(0)
pat = re.compile(r'og\.jpg\?v=(\d+)')
out, ok = {}, True
for r, _, fs in os.walk('app'):
    if 'index.html' not in fs: continue
    p = os.path.join(r, 'index.html')
    s = open(p, 'rb').read().decode('utf-8')
    m = pat.search(s)
    if os.path.normpath(p) == os.path.normpath(ROOT):
        if m:
            s = pat.sub('og_ko.jpg?v=1', s)
            s = s.replace('사진은 전 세계 공통 (app/og.jpg, 바꾸면 ?v= 숫자 올리기)',
                          '한국어 사진은 app/og_ko.jpg · 다른 언어는 app/og.jpg (바꾸면 ?v= 숫자 올리기)')
            out[p] = s; print('✔ [한국어] app/index.html → og_ko.jpg (파란소리)')
        else:
            ok = False; print('❌ [한국어] app/index.html 에서 og.jpg?v= 를 못 찾았어요')
    elif m:
        out[p] = pat.sub(lambda mm: 'og.jpg?v=' + str(int(mm.group(1)) + 1), s)
        print('✔', p.replace(os.sep, '/'), '→ og.jpg (ParanSori) 번호 올림')
    elif 'og.jpg' in s:
        ok = False; print('❌', p, 'og.jpg 는 있는데 ?v= 번호가 없어요')
if not ok:
    print('❌ 하나라도 실패해서 저장 안 했어요'); sys.exit(1)
open(og, 'wb').write(EN); print('✔ app/og.jpg 영어 그림으로 바꿈')
open(og_ko, 'wb').write(KO); print('✔ app/og_ko.jpg 한국어 그림 새로 넣음')
for p, s in out.items():
    open(p, 'wb').write(s.encode('utf-8'))
print('저장했어요')
print()
print('카카오 캐시 초기화할 주소:')
print('  https://ssing.kr/app/')
print('  https://ssing.kr/app/en/')
